25:  * const variables = extractVariableNames('obj.prop()')
26:  * ```
27:  *
28:  * @example
29:  * ```ts
30:  * // variables will be ['arr', 'needle']
31:  * const variables = extractVariableNames('arr.filter(v => v === needle)')
